effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat6;
vec4 u_xlat7;
bool u_xlatb7;
vec4 u_xlat8;
vec4 u_xlat9;
bvec3 u_xlatb9;
vec3 u_xlat10;
vec4 u_xlat11;
vec3 u_xlat12;
vec3 u_xlat13;
vec4 u_xlat14;
vec4 u_xlat15;
vec4 u_xlat16;
bvec4 u_xlatb16;
vec4 u_xlat17;
vec3 u_xlat19;
float u_xlat20;
float u_xlat21;
float u_xlat24;
vec2 u_xlat37;
float u_xlat42;
float u_xlat56;
int u_xlati60;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = _resolution.x / _resolution.y;
    u_xlat1.x = u_xlat1.x * acScreenNorm.x;
    u_xlat1.y = acScreenNorm.y;
    u_xlat1.xy = _position.xy * vec2(-1.0, 1.0) + u_xlat1.xy;
    u_xlat37.xy = vec2(vec2(_seed, _seed)) * vec2(188.298065, 56.7870369);
    u_xlatb2.xy = greaterThanEqual(u_xlat37.xyxx, (-u_xlat37.xyxx)).xy;
    u_xlat37.xy = fract(abs(u_xlat37.xy));
    {
        vec2 hlslcc_movcTemp = u_xlat37;
        hlslcc_movcTemp.x = (u_xlatb2.x) ? u_xlat37.x : (-u_xlat37.x);
        hlslcc_movcTemp.y = (u_xlatb2.y) ? u_xlat37.y : (-u_xlat37.y);
        u_xlat37 = hlslcc_movcTemp;
    }
    u_xlat1.xy = u_xlat37.xy * vec2(4.36499977, 7.70100021) + u_xlat1.xy;
    u_xlat1.xy = u_xlat1.xy + vec2(-0.5, -0.5);
    u_xlat1.xy = u_xlat1.xy / vec2(_scale.x, _scale.y);
    u_xlat2.z = _evolution;
    u_xlat3.x = float(0.0);
    u_xlat3.w = float(1.0);
    u_xlat4.x = float(0.0);
    u_xlat4.w = float(1.0);
    u_xlat5.x = float(0.0);
    u_xlat5.w = float(1.0);
    u_xlat37.xy = u_xlat1.xy;
    u_xlat56 = 0.0;
    u_xlat6 = float(1.0);
    u_xlat24 = float(0.5);
    u_xlat42 = float(1.0);
    u_xlati60 = int(0);
    while(true){
        u_xlatb7 = u_xlati60>=int(_complexity);
        if(u_xlatb7){break;}
        u_xlat2.xy = u_xlat37.xy * vec2(u_xlat6);
        u_xlat7.x = dot(u_xlat2.xyz, vec3(0.333333343, 0.333333343, 0.333333343));
        u_xlat7.xyz = u_xlat2.xyz + u_xlat7.xxx;
        u_xlat7.xyz = floor(u_xlat7.xyz);
        u_xlat8.xyz = u_xlat2.xyz + (-u_xlat7.xyz);
        u_xlat2.x = dot(u_xlat7.xyz, vec3(0.166666672, 0.166666672, 0.166666672));
        u_xlat8.xyz = u_xlat2.xxx + u_xlat8.xyz;
        u_xlatb9.xyz = greaterThanEqual(u_xlat8.zxyz, u_xlat8.xyzx).xyz;
        u_xlat10.x = u_xlatb9.y ? float(1.0) : 0.0;
        u_xlat10.y = u_xlatb9.z ? float(1.0) : 0.0;
        u_xlat10.z = u_xlatb9.x ? float(1.0) : 0.0;
;
        u_xlat9.x = (u_xlatb9.x) ? float(0.0) : float(1.0);
        u_xlat9.y = (u_xlatb9.y) ? float(0.0) : float(1.0);
        u_xlat9.z = (u_xlatb9.z) ? float(0.0) : float(1.0);
        u_xlat11.xyz = min(u_xlat9.xyz, u_xlat10.xyz);
        u_xlat9.xyz = max(u_xlat9.xyz, u_xlat10.xyz);
        u_xlat10.xyz = u_xlat8.xyz + (-u_xlat11.xyz);
        u_xlat10.xyz = u_xlat10.xyz + vec3(0.166666672, 0.166666672, 0.166666672);
        u_xlat12.xyz = u_xlat8.xyz + (-u_xlat9.xyz);
        u_xlat12.xyz = u_xlat12.xyz + vec3(0.333333343, 0.333333343, 0.333333343);
        u_xlat13.xyz = u_xlat8.xyz + vec3(-0.5, -0.5, -0.5);
        u_xlat14.xyz = u_xlat7.xyz * vec3(0.00346020772, 0.00346020772, 0.00346020772);
        u_xlat14.xyz = floor(u_xlat14.xyz);
        u_xlat7.xyz = (-u_xlat14.xyz) * vec3(289.0, 289.0, 289.0) + u_xlat7.xyz;
        u_xlat3.y = u_xlat11.z;
        u_xlat3.z = u_xlat9.z;
        u_xlat14 = u_xlat3 + u_xlat7.zzzz;
        u_xlat15 = u_xlat14 * vec4(34.0, 34.0, 34.0, 34.0) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat14 = u_xlat14 * u_xlat15;
        u_xlat15 = u_xlat14 * vec4(0.00346020772, 0.00346020772, 0.00346020772, 0.00346020772);
        u_xlat15 = floor(u_xlat15);
        u_xlat14 = (-u_xlat15) * vec4(289.0, 289.0, 289.0, 289.0) + u_xlat14;
        u_xlat14 = u_xlat7.yyyy + u_xlat14;
        u_xlat4.y = u_xlat11.y;
        u_xlat4.z = u_xlat9.y;
        u_xlat14 = u_xlat4 + u_xlat14;
        u_xlat15 = u_xlat14 * vec4(34.0, 34.0, 34.0, 34.0) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat14 = u_xlat14 * u_xlat15;
        u_xlat15 = u_xlat14 * vec4(0.00346020772, 0.00346020772, 0.00346020772, 0.00346020772);
        u_xlat15 = floor(u_xlat15);
        u_xlat14 = (-u_xlat15) * vec4(289.0, 289.0, 289.0, 289.0) + u_xlat14;
        u_xlat7 = u_xlat7.xxxx + u_xlat14;
        u_xlat5.y = u_xlat11.x;
        u_xlat5.z = u_xlat9.x;
        u_xlat7 = u_xlat5 + u_xlat7;
        u_xlat9 = u_xlat7 * vec4(34.0, 34.0, 34.0, 34.0) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat7 = u_xlat7 * u_xlat9;
        u_xlat9 = u_xlat7 * vec4(0.00346020772, 0.00346020772, 0.00346020772, 0.00346020772);
        u_xlat9 = floor(u_xlat9);
        u_xlat7 = (-u_xlat9) * vec4(289.0, 289.0, 289.0, 289.0) + u_xlat7;
        u_xlat9 = u_xlat7 * vec4(0.0204081647, 0.0204081647, 0.0204081647, 0.0204081647);
        u_xlat9 = floor(u_xlat9);
        u_xlat7 = (-u_xlat9) * vec4(49.0, 49.0, 49.0, 49.0) + u_xlat7;
        u_xlat9 = u_xlat7 * vec4(0.142857149, 0.142857149, 0.142857149, 0.142857149);
        u_xlat9 = floor(u_xlat9);
        u_xlat7 = (-u_xlat9) * vec4(7.0, 7.0, 7.0, 7.0) + u_xlat7;
        u_xlat9 = u_xlat9 * vec4(0.285714298, 0.285714298, 0.285714298, 0.285714298) + vec4(-0.928571403, -0.928571403, -0.928571403, -0.928571403);
        u_xlat7 = u_xlat7.xzyw * vec4(0.285714298, 0.285714298, 0.285714298, 0.285714298) + vec4(-0.928571403, -0.928571403, -0.928571403, -0.928571403);
        u_xlat11 = -abs(u_xlat9) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat11 = -abs(u_xlat7.xzwy) + u_xlat11.xywz;
        u_xlat14.xz = floor(u_xlat9.xy);
        u_xlat14.yw = floor(u_xlat7.xz);
        u_xlat14 = u_xlat14 * vec4(2.0, 2.0, 2.0, 2.0) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat15.xz = floor(u_xlat9.zw);
        u_xlat15.yw = floor(u_xlat7.yw);
        u_xlat15 = u_xlat15 * vec4(2.0, 2.0, 2.0, 2.0) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlatb16 = greaterThanEqual(vec4(0.0, 0.0, 0.0, 0.0), u_xlat11.xywz);
        u_xlat16.x = (u_xlatb16.x) ? float(-1.0) : float(-0.0);
        u_xlat16.y = (u_xlatb16.y) ? float(-1.0) : float(-0.0);
        u_xlat16.z = (u_xlatb16.z) ? float(-1.0) : float(-0.0);
        u_xlat16.w = (u_xlatb16.w) ? float(-1.0) : float(-0.0);
        u_xlat17.xz = u_xlat9.xy;
        u_xlat17.yw = u_xlat7.xz;
        u_xlat14 = u_xlat14.zwxy * u_xlat16.yyxx + u_xlat17.zwxy;
        u_xlat7.xz = u_xlat9.zw;
        u_xlat7 = u_xlat15 * u_xlat16.zzww + u_xlat7;
        u_xlat9.xy = u_xlat14.zw;
        u_xlat9.z = u_xlat11.x;
        u_xlat15.x = dot(u_xlat9.xyz, u_xlat9.xyz);
        u_xlat14.z = u_xlat11.y;
        u_xlat15.y = dot(u_xlat14.xyz, u_xlat14.xyz);
        u_xlat16.xy = u_xlat7.xy;
        u_xlat16.z = u_xlat11.w;
        u_xlat15.z = dot(u_xlat16.xyz, u_xlat16.xyz);
        u_xlat11.xy = u_xlat7.zw;
        u_xlat15.w = dot(u_xlat11.xyz, u_xlat11.xyz);
        u_xlat7 = (-u_xlat15) * vec4(0.853734732, 0.853734732, 0.853734732, 0.853734732) + vec4(1.79284286, 1.79284286, 1.79284286, 1.79284286);
        u_xlat9.xyz = u_xlat7.xxx * u_xlat9.xyz;
        u_xlat14.xyz = u_xlat7.yyy * u_xlat14.xyz;
        u_xlat7.xyz = u_xlat7.zzz * u_xlat16.xyz;
        u_xlat11.xyz = u_xlat7.www * u_xlat11.xyz;
        u_xlat15.x = dot(u_xlat8.xyz, u_xlat8.xyz);
        u_xlat15.y = dot(u_xlat10.xyz, u_xlat10.xyz);
        u_xlat15.z = dot(u_xlat12.xyz, u_xlat12.xyz);
        u_xlat15.w = dot(u_xlat13.xyz, u_xlat13.xyz);
        u_xlat15 = (-u_xlat15) + vec4(0.600000024, 0.600000024, 0.600000024, 0.600000024);
        u_xlat15 = max(u_xlat15, vec4(0.0, 0.0, 0.0, 0.0));
        u_xlat15 = u_xlat15 * u_xlat15;
        u_xlat15 = u_xlat15 * u_xlat15;
        u_xlat8.x = dot(u_xlat9.xyz, u_xlat8.xyz);
        u_xlat8.y = dot(u_xlat14.xyz, u_xlat10.xyz);
        u_xlat8.z = dot(u_xlat7.xyz, u_xlat12.xyz);
        u_xlat8.w = dot(u_xlat11.xyz, u_xlat13.xyz);
        u_xlat2.x = dot(u_xlat15, u_xlat8);
        u_xlat2.x = u_xlat2.x * 42.0;
        u_xlat2.x = -abs(u_xlat2.x) + 0.899999976;
        u_xlat2.x = u_xlat2.x * u_xlat2.x;
        u_xlat20 = u_xlat24 * u_xlat2.x;
        u_xlat21 = u_xlat2.x * u_xlat24 + u_xlat56;
        u_xlat56 = u_xlat20 * u_xlat42 + u_xlat21;
        u_xlat6 = u_xlat6 + u_xlat6;
        u_xlat37.xy = vec2(_phase.x, _phase.y) * vec2(-1.0, 1.0) + u_xlat37.xy;
        u_xlat24 = u_xlat24 * 0.5;
        u_xlati60 = u_xlati60 + 1;
        u_xlat42 = u_xlat2.x;
    }
    u_xlat1.x = u_xlat56 * _intensity;
    u_xlat19.xyz = _color1.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat19.xyz = _color1.xyz * u_xlat19.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.xyz = u_xlat19.xyz * _color1.xyz;
    u_xlat19.xyz = _color2.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat19.xyz = _color2.xyz * u_xlat19.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.w = _color1.w;
    u_xlat3.xyz = _color2.xyz * u_xlat19.xyz + (-u_xlat2.xyz);
    u_xlat3.w = (-u_xlat2.w) + _color2.w;
    u_xlat1 = u_xlat1.xxxx * u_xlat3 + u_xlat2;
    u_xlat2 = u_xlat0.wwww * u_xlat1;
    u_xlat1.x = (-u_xlat1.w) * u_xlat0.w + 1.0;
    u_xlat1 = u_xlat0 * u_xlat1.xxxx + u_xlat2;
    u_xlatb2.x = int(_blend_mode)==1;
    u_xlat3 = u_xlat0 * u_xlat1;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat1.xyz;
    u_xlat4.w = u_xlat0.w;
    u_xlat2 = (u_xlatb2.x) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat1.xyz;
    u_xlat1 = (int(_blend_mode) != 0) ? u_xlat2 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
